// @vitest-environment jsdom
/**
 * #385: the transcribing screen must never show fabricated percents —
 * stage boundaries alone leave the bar indeterminate, counted work
 * units render as real step counts, and a percent appears only for a
 * genuine whole-job fraction.
 */
import { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  createJobView,
  reduceJobEvent,
  type JobView,
} from "../sidecar/jobView";
import type { JobEventPayload } from "../sidecar/protocol";
import type { CommandSurface } from "../commands/registry";
import { TranscriptionView } from "./TranscriptionView";
import { installJsdomStubs } from "../quality/testEnv";

(globalThis as Record<string, unknown>).IS_REACT_ACT_ENVIRONMENT = true;
installJsdomStubs();

let root: Root | null = null;
let host: HTMLDivElement | null = null;

const commands: CommandSurface = {
  invoke: vi.fn(() => true),
  isEnabled: () => true,
  isVisible: () => true,
  title: (id) => id,
  shortcutLabel: () => undefined,
};

function ev(over: Partial<JobEventPayload>): JobEventPayload {
  return { jobId: "job-1", phase: "progress", ...over };
}

function render(job: JobView | null): void {
  host = document.createElement("div");
  document.body.appendChild(host);
  root = createRoot(host);
  act(() => {
    root!.render(<TranscriptionView job={job} commands={commands} />);
  });
}

afterEach(() => {
  act(() => root?.unmount());
  root = null;
  host?.remove();
  host = null;
});

function progressBar(): HTMLElement | null {
  return host?.querySelector('[role="progressbar"]') ?? null;
}

describe("TranscriptionView progress honesty (#385)", () => {
  it("stage boundary alone stays indeterminate — no fabricated %", () => {
    let job = createJobView("job-1", "transcription", 0);
    job = reduceJobEvent(job, ev({ stage: "transcribing" }));
    render(job);
    const bar = progressBar();
    expect(bar).not.toBeNull();
    // Indeterminate: no aria-valuenow at all.
    expect(bar?.getAttribute("aria-valuenow")).toBeNull();
    // No percent text and no step text anywhere.
    expect(host?.textContent).not.toMatch(/\d+%/);
    expect(host?.textContent).not.toMatch(/\d+\/\d+/);
  });

  it("counted stage units render as real step counts + determinate bar", () => {
    let job = createJobView("job-1", "transcription", 0);
    job = reduceJobEvent(job, ev({ stage: "rendering" }));
    job = reduceJobEvent(
      job,
      ev({ stage: "rendering", step: 2, totalSteps: 5 }),
    );
    render(job);
    const bar = progressBar();
    expect(bar?.getAttribute("aria-valuenow")).toBe("0.4");
    expect(host?.textContent).toContain("2/5");
    // A step count is never presented as a percentage.
    expect(host?.textContent).not.toMatch(/\d+%/);
  });

  it("a genuine whole-job fraction shows the percent", () => {
    let job = createJobView("job-1", "demoLongTask", 0);
    job = reduceJobEvent(job, ev({ progress: 0.42 }));
    render(job);
    const bar = progressBar();
    expect(bar?.getAttribute("aria-valuenow")).toBe("0.42");
    expect(host?.textContent).toContain("42%");
  });

  it("null job renders the same indeterminate shell", () => {
    render(null);
    expect(progressBar()?.getAttribute("aria-valuenow")).toBeNull();
  });
});

import { useEffect, useRef, useState } from "react";
import { ja } from "../strings/ja";
import { HsButton } from "./primitives/Button";
import { HsProgress } from "./primitives/Progress";
import type { CommandSurface } from "../commands/registry";
import {
  initialStages,
  type JobView,
  type StageStatus,
  type TranscriptionStageId,
} from "../sidecar/jobView";

/**
 * Transcribing screen body (GUI_UX_SPEC §5, issue UI-040).
 *
 * - Not a modal: rendered inside ScoreWorkspace's score region while the
 *   rest of the shell (transport, waveform, non-score commands) stays
 *   usable.
 * - Stage list is driven ONLY by engine-reported `stage` fields — a job
 *   that reports none (spike demoLongTask) shows every stage pending
 *   rather than a guessed position.
 * - The progress bar is determinate only on real measured work — a
 *   whole-job `progress` fraction for job kinds that compute one, or
 *   the counted units (`step`/`totalSteps`) of the active stage.
 *   #385: stage boundaries carry no fabricated percentage, so a
 *   blocking inference stays honestly indeterminate.
 * - キャンセル sends cooperative `job.cancel`; the button then shows the
 *   honest pending state until the terminal `cancelled` event arrives.
 * - `job` is null while the engine is still spawning/handshaking — the
 *   view renders the same shell indeterminate, with cancel disabled.
 *
 * Screen-reader semantics: the region is labelled, the progress bar is a
 * real `progressbar` (Fluent), the active stage line is `aria-live`, and
 * each stage item exposes `aria-current="step"` while active.
 */

/** mm:ss elapsed readout — tabular-nums friendly, no unstable ETA. */
export function formatElapsedMs(ms: number): string {
  const totalSec = Math.max(0, Math.floor(ms / 1000));
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

function stageLabel(id: TranscriptionStageId, status: StageStatus): string {
  const copy = ja.transcription.stages[id];
  return status === "done"
    ? copy.done
    : status === "active"
      ? copy.active
      : copy.pending;
}

export function TranscriptionView({
  job,
  commands,
}: {
  /** Live tracked job view from the transcription session — null while
   *  the engine is still starting (spawn + handshake). */
  job: JobView | null;
  /** Command surface — キャンセル routes through `score.cancelTranscription`
   *  so the button and any future menu item stay the same command. */
  commands: CommandSurface;
}) {
  const cancelling = job?.phase === "cancelling";
  const [now, setNow] = useState(() => Date.now());
  // Before job.start resolves there is no startedAt — the wait is part of
  // the job from the user's point of view, so count from mount.
  const mountedAt = useRef(Date.now());

  // Elapsed readout — 500 ms tick, well under the §28 update budget.
  useEffect(() => {
    const t = window.setInterval(() => setNow(Date.now()), 500);
    return () => window.clearInterval(t);
  }, []);
  const elapsed = formatElapsedMs(now - (job?.startedAt ?? mountedAt.current));

  const stages = job?.stages ?? initialStages();
  const activeIndex = job?.activeStageIndex ?? -1;
  const progress = job?.progress ?? null;
  const activeStage = activeIndex >= 0 ? stages[activeIndex] : null;
  const activeStageText = activeStage
    ? stageLabel(activeStage.id, "active")
    : ja.transcription.running;
  const stepCount = job?.stepCount ?? null;
  // #385: the bar is determinate only on real fractions — a whole-job
  // `progress` (job kinds that measure one) or the counted units of
  // the active stage; otherwise it stays honestly indeterminate.
  const barValue =
    progress ??
    (stepCount !== null ? stepCount.step / stepCount.total : undefined);
  const percent = progress !== null ? Math.round(progress * 100) : null;
  const stepText =
    stepCount !== null ? `${stepCount.step}/${stepCount.total}` : null;

  return (
      // No role=status here: the container holds a ticking elapsed readout,
      // and a live region on it would announce every 500ms tick. Only the
      // dedicated stage line below is aria-live.
      <div className="hs-transcribing">
        <h2 className="hs-transcribing__title">{ja.transcription.running}</h2>

        {/* Screen-reader progress: only the changing line is live, not the
            whole list — stage transitions announce once, politely. */}
        <span className="hs-visually-hidden" aria-live="polite">
          {activeStageText}
        </span>

        <HsProgress
          label={ja.transcription.progressAria}
          value={barValue}
          description={activeStageText}
        />
        <div className="hs-transcribing__meta">
          {percent !== null ? (
            <span className="hs-transcribing__percent">{percent}%</span>
          ) : null}
          {stepText !== null ? (
            <span className="hs-transcribing__steps">{stepText}</span>
          ) : null}
          <span className="hs-transcribing__elapsed">
            {ja.transcription.elapsedLabel} {elapsed}
          </span>
        </div>

        <ul className="hs-stage-list" aria-label={ja.transcription.progressAria}>
          {stages.map((stage, i) => (
            <li
              key={stage.id}
              className="hs-stage-list__item"
              data-state={stage.status}
              aria-current={i === activeIndex ? "step" : undefined}
            >
              <span className="hs-stage-list__icon" aria-hidden="true">
                {stage.status === "done"
                  ? "✓"
                  : stage.status === "active"
                    ? "●"
                    : "○"}
              </span>
              <span>{stageLabel(stage.id, stage.status)}</span>
            </li>
          ))}
        </ul>

        <p className="hs-transcribing__note">{ja.transcription.note}</p>

        <HsButton
          variant="secondary"
          loading={cancelling}
          disabled={
            job == null || !commands.isEnabled("score.cancelTranscription")
          }
          onClick={() => commands.invoke("score.cancelTranscription")}
        >
          {cancelling ? ja.transcription.cancelling : ja.transcription.cancel}
        </HsButton>
      </div>
  );
}

/**
 * Job-event → view-state tracker (GUI_UX_SPEC §5).
 *
 * Pure reducer: it folds `job.event` payloads into the stage list +
 * progress the transcribing screen renders. Honesty rules from the spec
 * and JAPANESE_UI_COPY §5 are enforced structurally here:
 *
 * - a stage is only `done`/`active` when the engine actually reported it —
 *   jobs without `stage` fields (e.g. `demoLongTask` on the spike worker)
 *   leave every stage pending and the UI must not fake a position;
 * - `progress` is only set when the engine emitted a real fraction;
 * - exactly one terminal phase ends the job (`completed` | `cancelled` |
 *   `failed`); later events for the same job are ignored.
 */

import {
  ERR,
  type JobEventPayload,
  type ProtocolErrorObject,
} from "./protocol";

/** Engine pipeline stage ids — keys of `transcription.stages.*` in the
 *  copy deck (protocol/copy/ja-JP.json), in pipeline order. */
export const TRANSCRIPTION_STAGE_IDS = [
  "preparing_audio",
  "transcribing",
  "cleaning",
  "analyzing_rhythm",
  "quantizing",
  "building_score",
  "rendering",
] as const;

export type TranscriptionStageId = (typeof TRANSCRIPTION_STAGE_IDS)[number];

export type StageStatus = "pending" | "active" | "done";

export interface StageView {
  id: TranscriptionStageId;
  status: StageStatus;
}

export type JobViewPhase =
  | "running"
  | "cancelling"
  | "completed"
  | "cancelled"
  | "failed";

/**
 * What the transcribing screen renders for one in-flight (or just-ended)
 * job. `stages` always lists all seven stages; `progress` is the engine's
 * real fraction or null (indeterminate).
 */
export interface JobView {
  jobId: string;
  jobKind: string;
  phase: JobViewPhase;
  stages: StageView[];
  /** Real 0–1 fraction reported by the engine, else null → indeterminate. */
  progress: number | null;
  // #385: counted work units of the ACTIVE stage (`step`/`totalSteps`)
  // — real measured progress inside a stage, e.g. verified parts 2/5.
  // Null when the stage does not count units (blocking inference) or
  // none have completed yet; reset on every stage transition so a new
  // stage never inherits the previous one's count.
  stepCount: { readonly step: number; readonly total: number } | null;
  /** Index of the active stage, or -1 when the engine reports no stages. */
  activeStageIndex: number;
  /** Whether any `stage` field has been seen for this job. */
  hasStageInfo: boolean;
  /** Job-level error from the terminal `failed` event. */
  error: ProtocolErrorObject | null;
  /** `completed` payload — the score-data handoff consumed by UI-030. */
  result: unknown;
  startedAt: number;
}

export function initialStages(): StageView[] {
  return TRANSCRIPTION_STAGE_IDS.map((id) => ({ id, status: "pending" }));
}

export function createJobView(
  jobId: string,
  jobKind: string,
  startedAt: number,
): JobView {
  return {
    jobId,
    jobKind,
    phase: "running",
    stages: initialStages(),
    progress: null,
    stepCount: null,
    activeStageIndex: -1,
    hasStageInfo: false,
    error: null,
    result: null,
    startedAt,
  };
}

function clampProgress(raw: unknown): number | null {
  if (typeof raw !== "number" || Number.isNaN(raw)) return null;
  return Math.min(1, Math.max(0, raw));
}

/**
 * Fold one `job.event` payload into the tracked view. Returns a new
 * JobView (immutably) so React state updates stay shallow-comparable.
 * Events for a different job, or events after a terminal phase, are
 * ignored (the worker emits exactly one terminal phase per job).
 */
export function reduceJobEvent(view: JobView, event: JobEventPayload): JobView {
  if (event.jobId !== view.jobId) return view;
  if (
    view.phase === "completed" ||
    view.phase === "cancelled" ||
    view.phase === "failed"
  ) {
    return view;
  }

  let { stages, activeStageIndex, hasStageInfo, progress } = view;
  let { stepCount } = view;

  const realProgress = clampProgress(event.progress);
  if (realProgress !== null) progress = realProgress;

  // [UI-040] `stage` is the only honest way to move the stage list — the
  // engine tells us where it is; we never guess from elapsed time.
  if (typeof event.stage === "string") {
    const idx = (TRANSCRIPTION_STAGE_IDS as readonly string[]).indexOf(
      event.stage,
    );
    if (idx >= 0) {
      hasStageInfo = true;
      // Stages only move forward — a job cannot un-finish a stage, so a
      // backwards `stage` is ignored rather than presented as progress.
      if (idx > activeStageIndex) {
        stages = stages.map((s, i) => ({
          ...s,
          status: i < idx ? "done" : i === idx ? "active" : "pending",
        }));
        activeStageIndex = idx;
        // #385: step counts are stage-local — a new stage starts
        // counting from nothing instead of inheriting the old count.
        stepCount = null;
      }
    }
  }

  // #385: counted units of the active stage — a measured `step` of
  // `totalSteps`, never a fabricated percentage.
  if (
    typeof event.step === "number" &&
    typeof event.totalSteps === "number" &&
    event.totalSteps > 0
  ) {
    stepCount = {
      step: Math.max(0, Math.min(event.step, event.totalSteps)),
      total: event.totalSteps,
    };
  }

  switch (event.phase) {
    case "completed":
      return {
        ...view,
        phase: "completed",
        stages: stages.map((s) => ({ ...s, status: "done" })),
        progress: 1,
        activeStageIndex: stages.length - 1,
        hasStageInfo,
        error: null,
        result: event.result ?? null,
      };
    case "cancelled":
      return {
        ...view,
        phase: "cancelled",
        stages,
        progress,
        activeStageIndex,
        hasStageInfo,
        error: null,
      };
    case "failed":
      return {
        ...view,
        phase: "failed",
        stages,
        progress,
        activeStageIndex,
        hasStageInfo,
        error: event.error ?? {
          code: ERR.JOB_FAILED,
          message: "job failed without an error object",
        },
      };
    default:
      // started | progress — running view.
      return {
        ...view,
        stages,
        progress,
        stepCount,
        activeStageIndex,
        hasStageInfo,
      };
  }
}

/**
 * Mark a cancel request as in-flight. The job is NOT done yet — the
 * terminal `cancelled` event is what ends it (cooperative cancel is a
 * request, not an instant kill); the UI shows an honest pending state in
 * the meantime.
 */
export function markCancelling(view: JobView): JobView {
  if (view.phase !== "running") return view;
  return { ...view, phase: "cancelling" };
}

/**
 * Supervisor-synthesized terminal failure (ADR-0002): when the worker
 * crashes or goes unresponsive mid-job, the engine never emits a terminal
 * event — the supervisor marks the job failed explicitly instead. This is
 * the same policy the UI-002 harness applies to killed workers.
 */
export function markJobDead(view: JobView, error: ProtocolErrorObject): JobView {
  if (
    view.phase === "completed" ||
    view.phase === "cancelled" ||
    view.phase === "failed"
  ) {
    return view;
  }
  return { ...view, phase: "failed", error };
}

/**
 * MockSidecarPort — an in-process emulation of `python -m hornscribe.worker`
 * for browser/dev mode and vitest.
 *
 * It implements the *real* wire contract (protocol/PROTOCOL.md), not a
 * friendly shortcut:
 *
 * - strict inbound validation with MALFORMED_MESSAGE replies (id recovered
 *   when possible, `id: null` otherwise) — same shape as protocol.py;
 * - handshake advertises capabilities; a protocol-version mismatch is
 *   refused with PROTOCOL_VERSION_MISMATCH and the mock exits 0 — refusal,
 *   not a crash, exactly like worker.py;
 * - `demoLongTask` mirrors jobs.py: cancel checkpoints between steps,
 *   deadlineMs → JOB_TIMEOUT, failAtStep → JOB_FAILED, terminal events
 *   exactly once;
 * - `transcription` is the UI-040 stand-in for the real transcription job
 *   kind (not yet in the spike worker): same step engine plus the [UI-040]
 *   `stage` field and a `result.reviewIssues` payload on completion, so
 *   the shell exercises the actual presentation path it will use with the
 *   real backend;
 * - `closeStdin()` = stdin EOF → cooperative cancel of any active job,
 *   then exit 0 (worker.py contract);
 * - `simulateCrash()` dies mid-job WITHOUT a terminal event — the
 *   supervisor must notice the exit itself (ADR-0002);
 * - `simulateHang()` wedges the dispatch loop (like `debug.hang`) so the
 *   client watchdog path can be exercised.
 *
 * Nothing here ships user-visible behavior in the packaged app — the port
 * factory only selects the mock outside the Tauri webview.
 */

import {
  ERR,
  PROTOCOL_VERSION,
  encodeFrame,
  type Envelope,
} from "./protocol";
import { TRANSCRIPTION_STAGE_IDS } from "./jobView";
import type { SidecarPort } from "./port";

const MOCK_METHODS = [
  "engine.handshake",
  "engine.ping",
  "engine.shutdown",
  "job.start",
  "job.cancel",
  "project.open",
];

/** Job kinds this emulation advertises in the handshake. `transcription`
 *  models the future real job kind; `demoLongTask` mirrors the spike
 *  worker so `capabilities.jobKinds` fallback logic is exercised. */
const MOCK_JOB_KINDS = ["transcription", "demoLongTask"];

interface MockJobParams {
  steps: number;
  stepDurationMs: number;
  deadlineMs?: number;
  failAtStep?: number;
}

interface MockJob {
  jobId: string;
  jobKind: string;
  params: MockJobParams;
  step: number;
  cancelled: boolean;
  done: boolean;
  timer: ReturnType<typeof setTimeout> | null;
  startedAt: number;
}

export interface MockSidecarOptions {
  /** Simulated worker pid reported by engine.ping / handshake. */
  pid?: number;
  /** Advertised job kinds — defaults to the full mock set; pass
   *  ["demoLongTask"] to emulate the UI-002 spike worker exactly. */
  jobKinds?: readonly string[];
}

export class MockSidecarPort implements SidecarPort {
  private readonly pid: number;
  private readonly jobKinds: readonly string[];
  private lineCbs = new Set<(line: string) => void>();
  private stderrCbs = new Set<(line: string) => void>();
  private exitCbs = new Set<(code: number | null) => void>();
  private alive = false;
  private wedged = false;
  private exited = false;
  private jobCounter = 0;
  private job: MockJob | null = null;
  private startedAt = 0;

  constructor(opts: MockSidecarOptions = {}) {
    this.pid = opts.pid ?? 4242;
    this.jobKinds = opts.jobKinds ?? MOCK_JOB_KINDS;
  }

  // ---- lifecycle ------------------------------------------------------

  async start(): Promise<void> {
    this.alive = true;
    this.exited = false;
    this.startedAt = Date.now();
    // stderr mirrors the real worker's lifecycle logs.
    this.stderr(
      `INFO hornscribe.worker: sidecar started pid=${this.pid} ` +
        `protocol=v${PROTOCOL_VERSION} hornscribe=0.1.0 (mock)`,
    );
  }

  closeStdin(): void {
    // stdin EOF → implicit graceful shutdown: cancel the active job
    // cooperatively (its terminal event still goes out), then exit 0.
    // A wedged dispatch loop never reads stdin — the EOF goes
    // unnoticed, exactly like the real worker's debug.hang (#233).
    if (!this.alive || this.wedged) return;
    const job = this.job;
    if (job && !job.done) {
      job.cancelled = true;
      this.finishJobNow(job);
    }
    this.exit(0);
  }

  kill(): void {
    this.simulateCrash();
  }

  /** Non-zero exit without a terminal job event — a real crash. */
  simulateCrash(code: number | null = 1): void {
    if (!this.alive) return;
    const job = this.job;
    if (job?.timer) clearTimeout(job.timer);
    // The job vanishes mid-flight with NO terminal event — the client
    // must mark it failed itself (ADR-0002 supervision contract).
    this.job = null;
    this.exit(code);
  }

  /** Wedge the dispatch loop: inbound frames are ignored, no frames out. */
  simulateHang(): void {
    this.wedged = true;
    const job = this.job;
    if (job?.timer) {
      clearTimeout(job.timer);
      job.timer = null;
    }
  }

  /** #233: model blocking ML inference — the dispatch loop still
   *  answers requests (job.cancel gets its ack), but the job thread is
   *  inside a non-interruptible call and never reaches the cancel
   *  checkpoint, so no terminal event ever arrives. */
  simulateBlockingInference(): void {
    const job = this.job;
    if (job?.timer) {
      clearTimeout(job.timer);
      job.timer = null;
    }
  }

  /** Test/dev hook: recover a wedged loop (not used in production). */
  unhang(): void {
    this.wedged = false;
    const job = this.job;
    if (job && !job.done && job.timer === null) {
      job.timer = setTimeout(() => this.runStep(job), job.params.stepDurationMs);
    }
  }

  private exit(code: number | null): void {
    if (this.exited) return;
    this.exited = true;
    this.alive = false;
    this.stderr("INFO hornscribe.worker: sidecar stopped (mock)");
    const cbs = [...this.exitCbs];
    for (const cb of cbs) cb(code);
    this.lineCbs.clear();
    this.stderrCbs.clear();
    this.exitCbs.clear();
  }

  // ---- subscriptions ----------------------------------------------------

  writeLine(line: string): void {
    if (!this.alive || this.wedged || this.exited) return;
    this.handleLine(line);
  }

  onLine(cb: (line: string) => void): () => void {
    this.lineCbs.add(cb);
    return () => this.lineCbs.delete(cb);
  }

  onStderr(cb: (line: string) => void): () => void {
    this.stderrCbs.add(cb);
    return () => this.stderrCbs.delete(cb);
  }

  onExit(cb: (code: number | null) => void): () => void {
    this.exitCbs.add(cb);
    return () => this.exitCbs.delete(cb);
  }

  // ---- frame IO ---------------------------------------------------------

  private emit(frame: Envelope): void {
    const line = encodeFrame(frame);
    for (const cb of [...this.lineCbs]) cb(line);
  }

  private stderr(line: string): void {
    for (const cb of [...this.stderrCbs]) cb(line);
  }

  private respond(id: string, method: string, payload: unknown): void {
    this.emit({
      v: PROTOCOL_VERSION,
      id,
      kind: "response",
      method,
      payload,
      error: null,
    });
  }

  private respondError(
    id: string | null,
    method: string | null,
    code: string,
    message: string,
    details?: unknown,
  ): void {
    this.emit({
      v: PROTOCOL_VERSION,
      id,
      kind: "response",
      method,
      payload: null,
      error: { code, message, ...(details !== undefined ? { details } : {}) },
    });
  }

  private emitEvent(method: string, payload: Record<string, unknown>): void {
    this.emit({
      v: PROTOCOL_VERSION,
      id: null,
      kind: "event",
      method,
      payload,
      error: null,
    });
  }

  // ---- dispatch (mirrors worker.py `_handle_line`) -----------------------

  private handleLine(line: string): void {
    const text = line.trim();
    let raw: unknown;
    try {
      raw = JSON.parse(text);
    } catch {
      this.respondError(null, null, ERR.MALFORMED_MESSAGE, "frame is not valid JSON");
      return;
    }
    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
      this.respondError(null, null, ERR.MALFORMED_MESSAGE, "envelope must be a JSON object");
      return;
    }
    const frame = raw as Record<string, unknown>;
    const recoverId =
      typeof frame.id === "string" && frame.id ? frame.id : null;
    // Mirror protocol.py ordering: a non-integer/missing `v` is
    // MALFORMED_MESSAGE; only an integer-but-unsupported `v` is
    // PROTOCOL_VERSION_MISMATCH.
    if (typeof frame.v !== "number" || !Number.isInteger(frame.v)) {
      this.respondError(
        recoverId,
        null,
        ERR.MALFORMED_MESSAGE,
        "'v' must be an integer protocol version",
      );
      return;
    }
    if (frame.v !== PROTOCOL_VERSION) {
      this.respondError(
        recoverId,
        null,
        ERR.PROTOCOL_VERSION_MISMATCH,
        `unsupported protocol version ${String(frame.v)}; worker speaks v${PROTOCOL_VERSION}`,
        { expected: PROTOCOL_VERSION, got: frame.v },
      );
      return;
    }
    if (frame.kind !== "request") {
      // Inbound response/event frames are logged and dropped — never
      // answered — so a reply loop is impossible.
      this.stderr(
        `WARNING hornscribe.worker: ignoring inbound ${String(frame.kind)} frame`,
      );
      return;
    }
    const id = recoverId;
    if (!id) {
      this.respondError(null, null, ERR.MALFORMED_MESSAGE, "request requires a non-empty string 'id'");
      return;
    }
    const method = frame.method;
    if (typeof method !== "string" || !method) {
      this.respondError(id, null, ERR.MALFORMED_MESSAGE, "request requires a non-empty string 'method'");
      return;
    }
    switch (method) {
      case "engine.handshake":
        return this.handleHandshake(id, frame.payload);
      case "engine.ping":
        return this.handlePing(id, frame.payload);
      case "engine.shutdown":
        return this.handleShutdown(id);
      case "job.start":
        return this.handleJobStart(id, frame.payload);
      case "job.cancel":
        return this.handleJobCancel(id, frame.payload);
      case "project.open":
        return this.handleProjectOpen(id, frame.payload);
      default:
        this.respondError(id, method, ERR.UNKNOWN_METHOD, `unknown method '${method}'`, {
          methods: MOCK_METHODS,
        });
    }
  }

  // ---- methods ------------------------------------------------------------

  private handleHandshake(id: string, payload: unknown): void {
    const params =
      typeof payload === "object" && payload !== null
        ? (payload as Record<string, unknown>)
        : {};
    const clientV = params.protocolVersion ?? PROTOCOL_VERSION;
    if (clientV !== PROTOCOL_VERSION) {
      // Refuse explicitly, then exit 0 — a worker must not serve a peer
      // it cannot talk to (worker.py contract).
      this.respondError(
        id,
        "engine.handshake",
        ERR.PROTOCOL_VERSION_MISMATCH,
        `client requested protocol v${String(clientV)}; worker speaks v${PROTOCOL_VERSION}`,
        { requested: clientV, supported: [PROTOCOL_VERSION] },
      );
      this.exit(0);
      return;
    }
    this.respond(id, "engine.handshake", {
      protocolVersion: PROTOCOL_VERSION,
      engineInfo: {
        name: "hornscribe-engine",
        version: "0.1.0",
        python: "0.0.0-mock",
        platform: "browser",
        pid: this.pid,
      },
      capabilities: {
        methods: MOCK_METHODS,
        jobKinds: [...this.jobKinds],
        maxConcurrentJobs: 1,
        cooperativeCancel: true,
        cancellationFallback: "terminate+restart",
        progressEvents: true,
        basicPitchAvailable: false,
      },
    });
  }

  private handlePing(id: string, payload: unknown): void {
    const echo =
      typeof payload === "object" && payload !== null
        ? (payload as Record<string, unknown>).echo
        : undefined;
    this.respond(id, "engine.ping", {
      echo,
      workerPid: this.pid,
      uptimeMs: Date.now() - this.startedAt,
    });
  }

  private handleShutdown(id: string): void {
    const active = this.job && !this.job.done ? this.job : null;
    this.respond(id, "engine.shutdown", {
      ok: true,
      activeJob: active ? active.jobId : null,
    });
    if (active) {
      active.cancelled = true;
      this.finishJobNow(active);
    }
    this.exit(0);
  }

  private handleJobStart(id: string, payload: unknown): void {
    if (typeof payload !== "object" || payload === null) {
      this.respondError(id, "job.start", ERR.INVALID_PARAMS, "job.start payload must be an object");
      return;
    }
    const p = payload as Record<string, unknown>;
    const jobKind = p.jobKind;
    if (typeof jobKind !== "string" || !jobKind) {
      this.respondError(id, "job.start", ERR.INVALID_PARAMS, "job.start requires a string 'jobKind'");
      return;
    }
    if (!this.jobKinds.includes(jobKind)) {
      this.respondError(id, "job.start", ERR.UNKNOWN_JOB_KIND, `unsupported jobKind '${jobKind}'`, {
        supported: [...this.jobKinds],
      });
      return;
    }
    if (this.job && !this.job.done) {
      this.respondError(id, "job.start", ERR.JOB_ALREADY_RUNNING, "a job is already running", {
        activeJobId: this.job.jobId,
        maxConcurrentJobs: 1,
      });
      return;
    }
    let params: MockJobParams;
    try {
      params = parseJobParams(p.params);
    } catch (e) {
      this.respondError(id, "job.start", ERR.INVALID_PARAMS, (e as Error).message);
      return;
    }
    this.jobCounter += 1;
    const jobId = `job-${String(this.jobCounter).padStart(4, "0")}`;
    const job: MockJob = {
      jobId,
      jobKind,
      params,
      step: 0,
      cancelled: false,
      done: false,
      timer: null,
      startedAt: Date.now(),
    };
    this.job = job;
    this.respond(id, "job.start", { jobId, jobKind, state: "accepted" });
    this.emitJobEvent(job, "started", {
      step: 0,
      progress: jobFraction(job, 0),
      totalSteps: params.steps,
      stage: stageFor(job, 0),
    });
    job.timer = setTimeout(() => this.runStep(job), params.stepDurationMs);
  }

  private handleJobCancel(id: string, payload: unknown): void {
    const jobId =
      typeof payload === "object" && payload !== null
        ? (payload as Record<string, unknown>).jobId
        : undefined;
    if (typeof jobId !== "string" || !jobId) {
      this.respondError(id, "job.cancel", ERR.INVALID_PARAMS, "job.cancel requires a string 'jobId'");
      return;
    }
    const job = this.job;
    if (!job || job.done || job.jobId !== jobId) {
      this.respondError(id, "job.cancel", ERR.JOB_NOT_FOUND, `no active job '${jobId}'`);
      return;
    }
    job.cancelled = true;
    this.respond(id, "job.cancel", { jobId: job.jobId, cancellation: "requested" });
  }

  /** #365 `project.open` — dev-fake emulation: decodes documentBase64,
   *  JSON.parses and applies the light local checks (the real worker's
   *  migrate+validate lives in Python — this exercises the wire shape
   *  for browser-dev project opens). `path` mode needs real fs access,
   *  which the mock honestly lacks. */
  private handleProjectOpen(id: string, payload: unknown): void {
    const params =
      typeof payload === "object" && payload !== null
        ? (payload as Record<string, unknown>)
        : {};
    if (typeof params.path === "string" && params.path) {
      this.respondError(
        id,
        "project.open",
        ERR.INVALID_PARAMS,
        "project.open by path requires the real worker (mock has no fs)",
      );
      return;
    }
    const b64 = params.documentBase64;
    if (typeof b64 !== "string" || !b64) {
      this.respondError(
        id,
        "project.open",
        ERR.INVALID_PARAMS,
        "project.open requires 'path' or 'documentBase64'",
      );
      return;
    }
    let doc: unknown;
    try {
      doc = JSON.parse(atob(b64)) as unknown;
    } catch {
      this.respondError(
        id,
        "project.open",
        ERR.INVALID_PARAMS,
        "project document is not valid JSON/base64",
      );
      return;
    }
    const data = doc as Record<string, unknown> | null;
    if (
      typeof data !== "object" ||
      data === null ||
      data.schemaVersion !== 1 ||
      typeof data.projectId !== "string" ||
      !data.projectId
    ) {
      this.respondError(
        id,
        "project.open",
        ERR.INVALID_PARAMS,
        "invalid or unsupported project document (mock)",
      );
      return;
    }
    this.respond(id, "project.open", { path: "", project: data });
  }

  // ---- job runner (mirrors run_demo_long_task) ----------------------------

  private runStep(job: MockJob): void {
    if (!this.alive || this.wedged || job.done) return;
    const next = job.step + 1;
    // Cooperative cancel: checked between steps, exactly like jobs.py.
    if (job.cancelled) {
      return this.finishJobNow(job);
    }
    if (
      job.params.deadlineMs !== undefined &&
      Date.now() - job.startedAt > job.params.deadlineMs
    ) {
      job.done = true;
    this.emitJobEvent(job, "failed", {
        step: job.step,
        progress: jobFraction(job, job.step),
        error: {
          code: ERR.JOB_TIMEOUT,
          message: `job exceeded deadlineMs=${job.params.deadlineMs}`,
        },
      });
      return;
    }
    if (job.params.failAtStep === next) {
      job.step = next;
      job.done = true;
      this.emitJobEvent(job, "failed", {
        step: next,
        progress: jobFraction(job, next - 1),
        error: {
          code: ERR.JOB_FAILED,
          message: `${job.jobKind} failed at step ${next} (failAtStep hook)`,
        },
      });
      return;
    }
    job.step = next;
    this.emitJobEvent(job, "progress", {
      step: next,
      progress: jobFraction(job, next),
      totalSteps: job.params.steps,
      stage: stageFor(job, next),
    });
    if (next >= job.params.steps) {
      job.done = true;
      this.emitJobEvent(job, "completed", {
        step: next,
        progress: 1,
        elapsedMs: Date.now() - job.startedAt,
        result: job.jobKind === "transcription" ? transcriptionResult() : { steps: job.params.steps },
      });
      return;
    }
    job.timer = setTimeout(() => this.runStep(job), job.params.stepDurationMs);
  }

  /** Emit the terminal `cancelled` event now (shutdown path or cancel
   *  observed at a step boundary). */
  private finishJobNow(job: MockJob): void {
    if (job.done) return;
    if (job.timer) clearTimeout(job.timer);
    job.done = true;
    this.emitJobEvent(job, "cancelled", {
      step: job.step,
      progress: jobFraction(job, job.step),
      reason: "cancel requested between steps",
    });
  }

  private emitJobEvent(
    job: MockJob,
    phase: string,
    fields: Record<string, unknown>,
  ): void {
    const body: Record<string, unknown> = {
      jobId: job.jobId,
      jobKind: job.jobKind,
      phase,
    };
    for (const [k, v] of Object.entries(fields)) {
      if (v !== undefined) body[k] = v;
    }
    this.emitEvent("job.event", body);
  }
}

// ---- helpers ---------------------------------------------------------------

/** `stage` field reported by stage-aware job kinds (UI-040 contract).
 *  `demoLongTask` reports none — the spike worker doesn't know stages.
 *  Step 0 (`started`) maps onto the first stage; each later step advances
 *  to the next stage, saturating at the last one for longer jobs. */
function stageFor(job: MockJob, step: number): string | undefined {
  if (job.jobKind !== "transcription") return undefined;
  return TRANSCRIPTION_STAGE_IDS[
    Math.min(step, TRANSCRIPTION_STAGE_IDS.length - 1)
  ];
}

// #385: a whole-job fraction is emitted only by job kinds that can
// truly measure one — `demoLongTask` (uniform steps). `transcription`
// mirrors the real engine: stage boundaries and counted units only;
// `progress` appears solely on the terminal `completed` event.
function jobFraction(job: MockJob, done: number): number | undefined {
  return job.jobKind === "transcription"
    ? undefined
    : done / job.params.steps;
}
function parseJobParams(raw: unknown): MockJobParams {
  if (raw === undefined || raw === null) {
    return { steps: TRANSCRIPTION_STAGE_IDS.length, stepDurationMs: 400 };
  }
  if (typeof raw !== "object") throw new Error("params must be an object");
  const p = raw as Record<string, unknown>;
  const int = (name: string, dflt: number | undefined, lo: number, hi: number) => {
    const v = p[name] ?? dflt;
    if (v === undefined) return undefined;
    if (typeof v !== "number" || !Number.isInteger(v)) {
      throw new Error(`params.${name} must be an integer`);
    }
    if (v < lo || v > hi) throw new Error(`params.${name} out of range [${lo}, ${hi}]`);
    return v;
  };
  const num = (name: string, dflt: number | undefined, lo: number, hi: number) => {
    const v = p[name] ?? dflt;
    if (v === undefined) return undefined;
    if (typeof v !== "number" || Number.isNaN(v)) {
      throw new Error(`params.${name} must be a number`);
    }
    if (v < lo || v > hi) throw new Error(`params.${name} out of range [${lo}, ${hi}]`);
    return v;
  };
  return {
    steps: int("steps", TRANSCRIPTION_STAGE_IDS.length, 1, 100000)!,
    stepDurationMs: num("stepDurationMs", 400, 0, 60000)!,
    deadlineMs: num("deadlineMs", undefined, 1, 3600000),
    failAtStep: int("failAtStep", undefined, 1, 100000),
  };
}

